<script>$(function(){var $party=$('.js-party'),lineNumber=0;function syncPartyRequired(){var required=$('[name="voucher_type"]').val()==='PAYMENT';$party.prop('required',required).closest('.col-md-6').find('.form-label').text(required?'คู่ค้า Supplier (จำเป็น)':'คู่ค้า (ถ้ามี)');} $party.select2({theme:'bootstrap-5',width:'100%',allowClear:true,placeholder:'ค้นหาคู่ค้า',ajax:{url:'{{ route('finance.payment-vouchers.party-options') }}',dataType:'json',delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(d,p){p.page=p.page||1;return d;}}});function initLine(){var n=lineNumber++;var $row=$('<div class="row g-2 align-items-end mb-2 voucher-line"><div class="col-md-7"><label class="form-label small">ใบแจ้งหนี้ AP</label><select class="form-select js-open-item" name="lines['+n+'][open_item_id]"></select></div><div class="col-md-3"><label class="form-label small">ยอดจัดสรร</label><input class="form-control" type="number" name="lines['+n+'][amount]" min="0.01" step="0.01"></div><div class="col-md-2"><button type="button" class="btn btn-outline-danger w-100 js-remove-line">ลบ</button></div></div>');$('#voucher-lines').append($row);$row.find('.js-open-item').select2({theme:'bootstrap-5',width:'100%',allowClear:true,placeholder:'ค้นหาเลขที่เอกสาร',ajax:{url:'{{ route('finance.payment-vouchers.open-item-options') }}',dataType:'json',delay:250,data:function(p){return{q:p.term||'',page:p.page||1,party_id:$party.val()||''};},processResults:function(d,p){p.page=p.page||1;return d;}}});}$('[name="voucher_type"]').on('change',function(){$('#voucher-lines').toggle(this.value==='PAYMENT');syncPartyRequired();});$('#add-voucher-line').on('click',initLine);$(document).on('click','.js-remove-line',function(){$(this).closest('.voucher-line').remove();});syncPartyRequired();window.erpAjaxForm({form:'#payment-voucher-form',redirect:true});});</script>
